% ORRERY reference scenario S6-geo-j2-sun-moon: GEO with J2, Sun and Moon (DE421), 7 days
% Generated by rain_atlas.orrery.gmat; run with: GmatConsole --run <this file>
SolarSystem.EphemerisSource = 'SPICE';
SolarSystem.SPKFilename = 'de421.bsp';
Earth.NutationUpdateInterval = 0;

Create Spacecraft Sat;
Sat.DateFormat = UTCGregorian;
Sat.Epoch = '15 Jan 2026 00:00:00.000';
Sat.CoordinateSystem = EarthMJ2000Eq;
Sat.DisplayStateType = Cartesian;
Sat.X = 42159.783599999995;
Sat.Y = 0.0;
Sat.Z = 0.0;
Sat.VX = 0.0;
Sat.VY = 3.07496908152212;
Sat.VZ = 0.005366838936401897;

Create ForceModel FM;
FM.CentralBody = Earth;
FM.PrimaryBodies = {Earth};
FM.GravityField.Earth.Degree = 2;
FM.GravityField.Earth.Order = 0;
FM.GravityField.Earth.PotentialFile = 'JGM3.cof';
FM.GravityField.Earth.TideModel = 'None';
FM.PointMasses = {Luna, Sun};
FM.Drag.AtmosphereModel = None;
FM.SRP = Off;
FM.RelativisticCorrection = Off;
FM.ErrorControl = RSSStep;

Create Propagator Prop;
Prop.FM = FM;
Prop.Type = RungeKutta89;
Prop.InitialStepSize = 60;
Prop.Accuracy = 1e-13;
Prop.MinStep = 0.001;
Prop.MaxStep = 2700;
Prop.MaxStepAttempts = 50;
Prop.StopIfAccuracyIsViolated = true;

Create ReportFile rf;
rf.Filename = 'C:/Users/chris/AppData/Local/Temp/claude/orrery-gmat/S6-geo-j2-sun-moon/S6-geo-j2-sun-moon.txt';
rf.Precision = 17;
rf.WriteHeaders = false;
rf.LeftJustify = On;
rf.ZeroFill = Off;

Create Variable I;

BeginMissionSequence;
Report rf Sat.ElapsedSecs Sat.A1ModJulian Sat.TAIModJulian Sat.TTModJulian Sat.TDBModJulian Sat.UTCModJulian Sat.EarthMJ2000Eq.X Sat.EarthMJ2000Eq.Y Sat.EarthMJ2000Eq.Z Sat.EarthMJ2000Eq.VX Sat.EarthMJ2000Eq.VY Sat.EarthMJ2000Eq.VZ Sat.EarthFixed.X Sat.EarthFixed.Y Sat.EarthFixed.Z Sat.EarthFixed.VX Sat.EarthFixed.VY Sat.EarthFixed.VZ Luna.EarthMJ2000Eq.X Luna.EarthMJ2000Eq.Y Luna.EarthMJ2000Eq.Z Sun.EarthMJ2000Eq.X Sun.EarthMJ2000Eq.Y Sun.EarthMJ2000Eq.Z;
For I = 1:2016;
   Propagate Prop(Sat) {Sat.ElapsedSecs = 300.0};
   Report rf Sat.ElapsedSecs Sat.A1ModJulian Sat.TAIModJulian Sat.TTModJulian Sat.TDBModJulian Sat.UTCModJulian Sat.EarthMJ2000Eq.X Sat.EarthMJ2000Eq.Y Sat.EarthMJ2000Eq.Z Sat.EarthMJ2000Eq.VX Sat.EarthMJ2000Eq.VY Sat.EarthMJ2000Eq.VZ Sat.EarthFixed.X Sat.EarthFixed.Y Sat.EarthFixed.Z Sat.EarthFixed.VX Sat.EarthFixed.VY Sat.EarthFixed.VZ Luna.EarthMJ2000Eq.X Luna.EarthMJ2000Eq.Y Luna.EarthMJ2000Eq.Z Sun.EarthMJ2000Eq.X Sun.EarthMJ2000Eq.Y Sun.EarthMJ2000Eq.Z;
EndFor;
